	ida_struct.set_member_cmt(ida_struct.get_member(struc, 187112), '''String: "https://firebasestorage.googleapis.com/v0/b/automatic-basketball-tra-6fab8.appspot.com/o/drills%2F15c08252-73e1-4dff-8b12-17fcdcf10897%2Fthumbnail.png\?alt=media&token=217e1d66-70c9-4711-a61e-8cd377ce7bb1"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 187104), '''String: "15c08252-73e1-4dff-8b12-17fcdcf10897"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 187096), '''String: "Work on balance, body control, and shot stability by creating momentum in different directions, then catching yourself and rising into your shot. This drill builds the ability to stay controlled when off balance, which is one of the most important parts of shooting."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 187088), '''String: "Controlled Falling Shooting Series"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 187080), '''String: "https://firebasestorage.googleapis.com/v0/b/automatic-basketball-tra-6fab8.appspot.com/o/drills%2F8cae119a-f460-4442-a7e2-4cb16bc8601a%2Fthumbnail.png\?alt=media&token=a8e4d67d-f4bb-4cf1-b255-b877d1059f20"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 187072), '''String: "8cae119a-f460-4442-a7e2-4cb16bc8601a"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 187064), '''String: "A full-speed conditioning and shooting drill that simulates catching in transition. Sprint, square up, and knock down the three -- no settling, no lazy catches."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 187056), '''String: "Shooting in Transition"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 187048), '''String: "https://firebasestorage.googleapis.com/v0/b/automatic-basketball-tra-6fab8.appspot.com/o/drills%2F6f970bd3-b781-4243-95fe-f264f2091f6a%2Fthumbnail.png\?alt=media&token=d592e44e-0381-4239-8ba2-63f3a77ad9fe"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 187040), '''String: "6f970bd3-b781-4243-95fe-f264f2091f6a"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 187032), '''String: "A footwork and finishing drill that sharpens your turnaround jumper from both elbows. Toss, chase, and spin into your shot."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 187024), '''String: "Elbow to Elbow"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 187016), '''String: "https://firebasestorage.googleapis.com/v0/b/automatic-basketball-tra-6fab8.appspot.com/o/drills%2Fd114c14d-4dfd-481e-9a67-2d24b88d93c2%2Fthumbnail.png\?alt=media&token=4dff3f6e-68a6-4bbf-b128-2bbdf45c2a70"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 187008), '''String: "d114c14d-4dfd-481e-9a67-2d24b88d93c2"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 187000), '''String: "The Allen Iverson signature crossover that uses a quick right foot tap as a spring mechanism to sell the attack left before crossing over at the last second to blow past the defender."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 186992), '''String: "AI Crossover"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 186984), '''String: "https://firebasestorage.googleapis.com/v0/b/automatic-basketball-tra-6fab8.appspot.com/o/drills%2F01f03fe8-0925-448c-8a1e-e1723a537475%2Fthumbnail.png\?alt=media&token=8f5b437f-d4ef-442e-a5d6-0ab88f7b5dae"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 186976), '''String: "01f03fe8-0925-448c-8a1e-e1723a537475"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 186968), '''String: "A deceptive dribble move where the ball handler uses a quick scissor motion with the right foot to generate lateral momentum and freeze the defender before crossing over and attacking."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 186960), '''String: "Scissor Step Crossover"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 186952), '''String: "https://firebasestorage.googleapis.com/v0/b/automatic-basketball-tra-6fab8.appspot.com/o/drills%2F7c5977b8-df48-401e-b787-6ddc51179042%2Fthumbnail.png\?alt=media&token=60e86486-a248-4fe9-bc24-90713eb51dfc"''', True)
