	ida_struct.set_member_cmt(ida_struct.get_member(struc, 186936), '''String: "A reaction and hustle drill that trains you to sprint after a live ball and get into your shot before it bounces twice. The passer throws the ball anywhere on the court -- you have no idea where it\'s going."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 186928), '''String: "Chase Down Catch and Shoot"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 186920), '''String: "https://firebasestorage.googleapis.com/v0/b/automatic-basketball-tra-6fab8.appspot.com/o/drills%2F706ce5cf-d221-4e18-adee-f8d9d7d777c1%2Fthumbnail.png\?alt=media&token=a4d870e8-556c-444b-8004-a0fa8729f89c"''', True)
