	ida_struct.set_member_cmt(ida_struct.get_member(struc, 186888), '''String: "https://firebasestorage.googleapis.com/v0/b/automatic-basketball-tra-6fab8.appspot.com/o/drills%2F7f0024e2-87a0-4f2c-8e29-802ca4bc0a99%2Fthumbnail.png\?alt=media&token=31d0eaeb-9176-4cbc-9bb2-b9f3d2fdb95c"''', True)
