	ida_struct.set_member_cmt(ida_struct.get_member(struc, 186856), '''String: "https://firebasestorage.googleapis.com/v0/b/automatic-basketball-tra-6fab8.appspot.com/o/drills%2Ff8b20f94-cec8-4bb8-9d46-8a4a05d106dd%2Fthumbnail.png\?alt=media&token=e1c76058-d46a-4a09-a1c3-705ce1950dee"''', True)
