	ida_struct.set_member_cmt(ida_struct.get_member(struc, 121464), '''String: "A more efficient solution is to split your build function into several widgets. This introduces a new context from which you can obtain the Scaffold. In this solution, you would have an outer widget that creates the Scaffold populated by instances of your new inner widgets, and then in these inner widgets you would use Scaffold.of().\nA less elegant but more expedient solution is assign a GlobalKey to the Scaffold, then use the key.currentState property to obtain the ScaffoldState rather than using the Scaffold.of() function."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 121456), '''String: "There are several ways to avoid this problem. The simplest is to use a Builder to get a context that is \"under\" the Scaffold. For an example of this, please see the documentation for Scaffold.of():\n  https://api.flutter.dev/flutter/material/Scaffold/of.html"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 121448), '''String: "No Scaffold ancestor could be found starting from the context that was passed to Scaffold.of(). This usually happens when the context provided is from the same StatefulWidget as that whose build function actually creates the Scaffold widget being sought."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 121440), '''String: "Scaffold.of() called with a context that does not contain a Scaffold."''', True)
